int main(void) { _libdnml_init();
    int total_tests = 0, passed_tests = 0; FILE* log_path;
    struct timespec start, end; clock_gettime(CLOCK_MONOTONIC, &start);
    limb_t *ret_buf = (limb_t *)malloc(BUF_SIZE * U64_BYTES); assert(ret_buf != NULL);
    crint ret = { .limbs = ret_buf, .n = 0, .cap = BUF_SIZE, .sign = 1 };
    log_path = fopen("../../algo_base/ci_add_sub_logs.log", "w+");
    if (log_path == NULL) { free(ret_buf); fputs("Can't open log file", stderr); return 1; }
    fputs("====================================================================\n", stdout);
    fputs("         LIB-DNML ALGORITHM TESTS - CRINT ADDITION/SUBTRACTION      \n", stdout);
    fputs("====================================================================\n", stdout);
    fputs("----- __CRINT_ADD_WC__ -----\n", log_path);
    for (int i = 0; i < CASE_CNT; ++i) { total_tests++;
        __CRINT_ADD_WC__(&ret, &add_cases[i].a, &add_cases[i].b);
        int8_t match = __CRINT_INTERNAL_CMP__(&ret, &add_cases[i].exp);
        if (!match) passed_tests++;
        else {
            fprintf(log_path,
                "[FAIL] ADD_WC Case %2d "
                "| Output struct: { .n = %zu, .sign = %" PRId8 " } "
                "| Exp Struct: { .n = %zu, .sign = %" PRId8 " }\n",
                i + 1, ret.n, ret.sign, add_cases[i].exp.n, add_cases[i].exp.sign
            );
            print_ci_limbs("ret", &ret, log_path);
            print_ci_limbs("exp", &add_cases[i].exp, log_path);
        }
    } fputs("Result written to test/calc_algo_test/algo_base/ci_add_sub_logs.log\n", stdout);


    fputs("----- __CRINT_SUB_WC__ -----\n", log_path);
    for (int i = 0; i < CASE_CNT; ++i) { total_tests++;
        __CRINT_SUB_WC__(&ret, &sub_cases[i].a, &sub_cases[i].b);
        int8_t match = __CRINT_INTERNAL_CMP__(&ret, &sub_cases[i].exp);
        if (!match) passed_tests++;
        else {
            fprintf(log_path,
                "[FAIL] SUB_WB Case %2d "
                "| Output struct: { .n = %zu, .sign = %" PRId8 " } "
                "| Exp Struct: { .n = %zu, .sign = %" PRId8 " }\n",
                i + 1, ret.n, ret.sign, sub_cases[i].exp.n, sub_cases[i].exp.sign
            );
            print_ci_limbs("ret", &ret, log_path);
            print_ci_limbs("exp", &sub_cases[i].exp, log_path);
        }
    } fputs("Result written to test/calc_algo_test/algo_base/ci_add_sub_logs.log\n", stdout);




    /* Summary output block */
    #undef CASE_CNT
    #undef MAX_SIZE
    #undef BUF_SIZE
    clock_gettime(CLOCK_MONOTONIC, &end); free(ret_buf); fclose(log_path);
    double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    fputs( "=========================================================\n", stdout);
    fputs( "TEST SUMMARY:\n", stdout);
    printf("+) Passed %-4d out of %-4d total compiled checks.\n", passed_tests, total_tests);
    printf("+) Success rate: %.2f%%\n", (total_tests > 0) ? ((passed_tests * 100.0) / total_tests) : 0.0);
    printf("+) Total Runtime: %lf ms\n", elapsed_time * 1000.0);
    fputs( "=========================================================\n", stdout);
    _libdnml_cleanup(); return 0;
}
